bool operator==(const Point& a, const Point& b) {
    return a.x == b.x && a.y == b.y;
}
struct PointHash {
    size_t operator()(const Point& p) const {
        return std::hash<int>{}(p.x) * 31 + std::hash<int>{}(p.y);
    }
};
std::unordered_set<Point, PointHash> u;  // needs hash and ==
